// src/components/ProductCard.jsx
import React from "react";
import "./ProductCard.css";

export default function ProductCard({
  image,
  name,
  category,
  price,
  oldPrice,
  isNew = false,
}) {
  return (
    <article className="pcard">
      <div className="pcard-image">
        {isNew && <span className="pcard-badge">Nouveau</span>}
        <img src={image} alt={name} />
        <button className="pcard-fav" aria-label="Add to wishlist">♡</button>
      </div>

      <div className="pcard-body">
        <h3 className="pcard-title">{name}</h3>
        <p className="pcard-cat">{category}</p>

        <div className="pcard-price">
          <span className="current">{price} DA</span>
          {oldPrice && <span className="old">{oldPrice} DA</span>}
        </div>
      </div>
    </article>
  );
}
